{ ${\left(2 x + 6\right)^{2}}$  }
   {  ${\left(2 x + 13\right)^{2}}$ }
     {  ${\left(2 x + 3\right)^{2}}$ }
    { \True  ${\left(2 x + 5\right)^{2}}$ }
\loigiai{
$\left(2 x + 2\right)^{2} + \left(12 x + 12\right) + 9=\left(2 x + 5\right)^{2}$
}\end{ex}

\begin{ex}%[8D2V1]
Thu gọn $\left(3 x - y\right)^{2} + \left(3 x - y\right) \left(12 x + 6 y\right) + \left(6 x + 3 y\right)^{2}$ bằng 
\choice
{  ${\left(9 x + 2 y + 9\right)^{2}}$ }
   {  ${\left(9 x + 2 y - 2\right)^{2}}$ }
     { ${\left(9 x + 2 y + 3\right)^{2}}$  }
    { \True  ${\left(9 x + 2 y\right)^{2}}$ }
\loigiai{
$\left(3 x - y\right)^{2} + \left(3 x - y\right) \left(12 x + 6 y\right) + \left(6 x + 3 y\right)^{2}=\left(9 x + 2 y\right)^{2}$
}\end{ex}
